describe('User Profile Update', () => {
    beforeEach(() => {
        cy.visit('/profile');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should display a confirmation message after successful profile update', () => {
        cy.get('input[name="username"]').clear().type('newUsername');
        cy.get('input[name="email"]').clear().type('newemail@example.com');
        cy.get('button[type="submit"]').click();

        cy.get('.confirmation-message').should('be.visible').and('contain', 'Profile updated successfully');
    });

    it('should display an error message when the profile update fails', () => {
        cy.intercept('POST', '/api/profile/update', {
            statusCode: 400,
            body: { message: 'Update failed. Please try again.' }
        }).as('updateProfile');

        cy.get('input[name="username"]').clear().type(''); // Invalid input
        cy.get('button[type="submit"]').click();

        cy.wait('@updateProfile');
        cy.get('.error-message').should('be.visible').and('contain', 'Update failed. Please try again.');
    });
});
